    <script>
        (function() {
            // --- 记忆化日夜切换逻辑 START ---
            const STORAGE_KEY = 'bond_system_v2_theme_pref';

            // 初始化检查
            const savedTheme = localStorage.getItem(STORAGE_KEY);
            const container = document.getElementById('bond-system-container-v2');
            if (savedTheme === 'night' && container) {
                container.classList.add('night-mode');
            }

            // 全局切换函数 (绑定在 window 上以便 onclick 调用)
            window.toggleBondTheme = function(e, btn) {
                // 阻止事件冒泡，防止触发 details 的折叠/展开
                e.preventDefault();
                e.stopPropagation();

                const wrapper = btn.closest('.bond-system-wrapper');
                if (!wrapper) return;

                // 切换样式类
                wrapper.classList.toggle('night-mode');

                // 保存状态
                const isNight = wrapper.classList.contains('night-mode');
                localStorage.setItem(STORAGE_KEY, isNight ? 'night' : 'day');
            };
            // --- 记忆化日夜切换逻辑 END ---


            function renderBondSystemV2() {
                const rawElem = document.getElementById('raw-bond-data-v2');
                const container = document.getElementById('bond-cards-container-v2');
                const pagination = document.getElementById('bond-pagination-v2');
                const indicator = pagination.querySelector('.bond-indicator');

                if (!rawElem || !container) return;

                let text = rawElem.innerHTML.trim();
                text = text.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

                // 解析数据
                // [NPC|...] 分隔不同角色
                const chunks = text.split('[');
                let npcs = [];
                let currentNPC = null;

                chunks.forEach(chunk => {
                    if (!chunk.trim()) return;
                    const content = chunk.split(']')[0];
                    const parts = content.split('|').map(s => s.trim());
                    const type = parts[0];

                    if (type === 'NPC') {
                        if (currentNPC) npcs.push(currentNPC);
                        currentNPC = {
                            name: parts[1] || 'Unknown',
                            tag: parts[2] || 'Target',
                            stats: []
                        };
                    } else if (type === 'Stat' && currentNPC) {
                        // V2格式: [Stat|Name|Val|Chg|Desc]
                        currentNPC.stats.push({
                            name: parts[1] || 'Attr',
                            value: parseInt(parts[2]) || 0,
                            change: parts[3] || '0',
                            desc: parts[4] || ''
                        });
                    }
                });
                if (currentNPC) npcs.push(currentNPC);

                // 渲染
                container.innerHTML = '';
                if (npcs.length === 0) {
                    container.innerHTML = '<div style="text-align:center;color:#b29a9a;padding:20px;">哥哥不小心发错了，请宝宝点开小铅笔看看哪里出错了吧</div>';
                    pagination.style.display = 'none';
                    return;
                }

                npcs.forEach((npc, index) => {
                    const card = document.createElement('div');
                    card.className = `npc-card ${index === 0 ? 'active' : ''}`;

                    let statsHtml = '';

                    const fixedStats = npc.stats.slice(0, 4);
                    const randomStats = npc.stats.slice(4);

                    const generateStatHtml = (s) => {
                        const val = s.value;
                        const chgStr = s.change;
                        let chgHtml = '';
                        let chgVal = parseInt(chgStr);

                        // 解析变动
                        if (chgStr !== '0' && chgStr !== '') {
                            const isUp = chgStr.includes('+') || chgVal > 0;
                            const isDown = chgStr.includes('-') || chgVal < 0;
                            if (isUp) chgHtml = `<span class="change-badge change-up">▲${chgStr.replace('+','')}</span>`;
                            if (isDown) chgHtml = `<span class="change-badge change-down">▼${chgStr.replace('-','')}</span>`;
                        }

                        // 进度条颜色逻辑：高危属性变红
                        let barClass = '';
                        if (['占有欲', '性欲', '杀意', '嫉妒', '黑化'].includes(s.name) && val > 70) {
                            barClass = 'fill-danger';
                        }

                        return `
                            <div class="stat-item">
                                <div class="stat-header">
                                    <span>${s.name}${chgHtml}</span>
                                    <span style="font-family:monospace;">${val}/100</span>
                                </div>
                                <div class="progress-bar-bg">
                                    <div class="progress-bar-fill ${barClass}" style="width: ${val}%"></div>
                                </div>
                                <div class="stat-desc">${s.desc}</div>
                            </div>
                        `;
                    };

                    statsHtml += `<div class="stat-group-title">❖ Core Stats</div>`;
                    statsHtml += `<div class="stat-list">`;
                    fixedStats.forEach(s => statsHtml += generateStatHtml(s));
                    statsHtml += `</div>`;

                    if (randomStats.length > 0) {
                        statsHtml += `<div class="stat-group-title" style="margin-top:15px;">❖ Dynamic Stats</div>`;
                        statsHtml += `<div class="stat-list">`;
                        randomStats.forEach(s => statsHtml += generateStatHtml(s));
                        statsHtml += `</div>`;
                    }

                    card.innerHTML = `
                        <div class="npc-header">
                            <i class="npc-name">${npc.name}</i>
                            <span class="npc-tag">${npc.tag}</span>
                        </div>
                        ${statsHtml}
                    `;
                    container.appendChild(card);
                });

                if (npcs.length > 1) {
                    pagination.style.display = 'flex';
                    indicator.textContent = `1 / ${npcs.length}`;
                } else {
                    pagination.style.display = 'none';
                }
            }

            setTimeout(renderBondSystemV2, 120);

            // 翻页逻辑
            if (typeof window.changeBondPageV2 !== 'function') {
                window.changeBondPageV2 = function(dir, btn) {
                    const wrapper = btn.closest('.bond-content');
                    const cards = wrapper.querySelectorAll('.npc-card');
                    const indicator = wrapper.querySelector('.bond-indicator');
                    let current = -1;
                    cards.forEach((c, i) => { if(c.classList.contains('active')) current = i; });
                    if(current === -1) return;
                    cards[current].classList.remove('active');
                    let next = (current + dir + cards.length) % cards.length;
                    cards[next].classList.add('active');
                    if (indicator) indicator.textContent = `${next + 1} / ${cards.length}`;
                }
            }
        })();
    </script>
</body>
</html>
