        }
        .video-overlay {
            position: absolute; top: 10px; left: 10px; right: 10px;
            display: flex; justify-content: space-between; font-size: 0.75em; text-shadow: 1px 1px 2px #000;
        }
        .stat-pill { background: rgba(0,0,0,0.6); padding: 2px 8px; border-radius: 10px; color: #fff; display: flex; align-items: center; gap: 4px; }

        /* 标题大小保持不变 */
        .live-main-title {
            color: #fff; font-size: 1.1em; font-weight: bold; text-align: center;
            z-index: 2; padding: 0 20px; text-shadow: 0 0 10px rgba(255,0,85,0.8);
        }
        .shame-tag {
            font-size: 0.7em; color: #ff0055; border: 1px solid #ff0055;
            padding: 2px 6px; border-radius: 4px; margin-top: 5px;
            background: rgba(255,0,85,0.1);
        }

        /* --- 数据统计栏 --- */
        .stats-bar {
            display: flex; justify-content: space-around; padding: 8px 0;
            background: #16161c; border-bottom: 1px solid #2a2a35;
        }
        .stat-item { text-align: center; }
        .stat-val { display: block; font-size: 1.0em; color: #fff; font-weight: bold; } /* 稍微调小一点点以适配整体 */
        .stat-label { font-size: 0.65em; color: #666; text-transform: uppercase; }
        .heat-val { color: #ff9900; }

        /* --- 弹幕区 (字体调小) --- */
        .section-title {
            font-size: 0.7em; color: #555; padding: 8px 15px 4px; font-weight: bold;
            text-transform: uppercase; letter-spacing: 1px;
        }
        .danmaku-container {
            padding: 5px 15px; min-height: 60px;
            display: flex; flex-direction: column; gap: 4px; /* 间距缩小 */
        }
        .dm-row {
            font-size: 0.75em; /* 关键修改：字体调小 */
            line-height: 1.4;
            wrap-option: nowrap; overflow: hidden; text-overflow: ellipsis;
        }
        .dm-user { color: #888; font-weight: bold; margin-right: 5px; }
        .dm-content { color: #ccc; }

        /* --- 评论区 (字体调小) --- */
        .comments-container {
            padding: 0 15px 15px; display: flex; flex-direction: column; gap: 8px; /* 间距缩小 */
            margin-top: 5px;
        }
        .cm-card {
            background: #1a1a20; border-radius: 6px; padding: 8px; /* 内边距缩小 */
            display: flex; gap: 8px; border: 1px solid #2a2a35;
        }
        .cm-avatar { font-size: 1.2em; min-width: 25px; text-align: center; padding-top: 2px; }
        .cm-main { flex: 1; }
        .cm-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 2px; }

        /* 关键修改：字体调小 */
        .cm-user { font-size: 0.8em; font-weight: bold; color: #aaa; }
        .cm-time { font-size: 0.65em; color: #555; }
        .cm-text { font-size: 0.8em; color: #ddd; line-height: 1.3; }

        .cm-card.donate {
            background: rgba(255, 153, 0, 0.05);
            border: 1px solid rgba(255, 153, 0, 0.3);
        }
        .donate-highlight {
            color: #ffaa00; font-weight: bold; display: block; margin-bottom: 2px;
            font-size: 0.9em;
        }

        .raw-live-data { display: none; }
    </style>

    <div class="live-stream-wrapper">
        <!-- 默认状态：折叠。图标为 ▼ -->
        <div class="live-header" onclick="toggleLiveV2(this)">
            <div style="display:flex; align-items:center;">
                <span class="live-status-badge">LIVE</span>
                <span class="live-title-preview" id="live-preview-title">点击展开直播间...</span>
            </div>
            <div class="toggle-icon">▼</div>
        </div>

        <!-- 默认状态：不含 open 类，即隐藏 -->
        <div class="live-body">
            <div id="live-renderer-v2"></div>
            <div class="raw-live-data" id="raw-live-data-v2">$1</div>
        </div>
    </div>

    <script>
        (function() {
            // 折叠逻辑 V2
            window.toggleLiveV2 = function(header) {
                const wrapper = header.closest('.live-stream-wrapper');
                const body = wrapper.querySelector('.live-body');
                const icon = header.querySelector('.toggle-icon');

                // 切换显示
                if (body.classList.contains('open')) {
                    body.classList.remove('open');
                    icon.style.transform = 'rotate(0deg)';
                    icon.textContent = '▼';
                } else {
                    body.classList.add('open');
                    icon.style.transform = 'rotate(180deg)';
                    icon.textContent = '▲';
                }
            };

            // 渲染逻辑
            function renderLiveV2() {
                const rawElem = document.getElementById('raw-live-data-v2');
                const container = document.getElementById('live-renderer-v2');
                const previewTitle = document.getElementById('live-preview-title');

                if (!rawElem || !container) return;

                let text = rawElem.innerHTML.trim();
                text = text.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

                const lines = text.split('[').filter(l => l.trim() !== '');
                let room = {};
                let dms = [];
                let cms = [];

                lines.forEach(line => {
                    const content = line.split(']')[0];
                    const parts = content.split('|').map(s => s.trim());
                    const type = parts[0];

                    if (type === 'Room') {
                        room = {
                            title: parts[1] || 'Unknown',
                            online: parts[2] || '0',
                            time: parts[3] || '0:00',
                            likes: parts[4] || '0',
                            heat: parts[5] || '0',
                            level: parts[6] || 'Normal'
                        };
                        // 更新折叠时的预览标题为真实标题
                        if (previewTitle) previewTitle.textContent = room.title;
                    } else if (type === 'DM') {
                        dms.push({ user: parts[1], text: parts[2] });
                    } else if (type === 'CM') {
                        cms.push({
                            user: parts[1],
                            avatar: parts[2] || '👤',
                            text: parts[3] || '',
                            time: parts[4] || 'Now'
                        });
                    }
                });

                // HTML构建
                let html = '';

                // 1. 顶部视频/信息区
                html += `
                    <div class="video-area">
                        <div class="video-overlay">
                            <span class="stat-pill">🔴 ${room.online || '0'}</span>
                            <span class="stat-pill">⏱️ ${room.time || '0:00'}</span>
                        </div>
                        <div class="live-main-title">${room.title}</div>
                        <div class="shame-tag">${room.level}</div>
                    </div>
                `;

                // 2. 数据条
                html += `
                    <div class="stats-bar">
                        <div class="stat-item"><span class="stat-val heat-val">🔥 ${room.heat}</span><span class="stat-label">热度</span></div>
                        <div class="stat-item"><span class="stat-val">❤️ ${room.likes}</span><span class="stat-label">点赞</span></div>
                    </div>
                `;

                // 3. 弹幕区 (自适应循环渲染)
                html += `<div class="section-title">⚡ 实时弹幕 (${dms.length})</div>`;
                html += `<div class="danmaku-container">`;
                dms.forEach(dm => {
                    html += `<div class="dm-row"><span class="dm-user">${dm.user}:</span><span class="dm-content">${dm.text}</span></div>`;
                });
                if(dms.length === 0) html += `<div class="dm-row" style="color:#555;">暂无弹幕...</div>`;
                html += `</div>`;

                // 4. 评论区 (自适应循环渲染)
                html += `<div class="section-title">💬 贵宾席 / 打赏 (${cms.length})</div>`;
                html += `<div class="comments-container">`;

                cms.forEach(cm => {
                    const isDonate = cm.text.includes('打赏') || cm.text.includes('金币');
                    let displayContent = cm.text;
                    let donateHtml = '';

                    if (isDonate) {
                        const match = cm.text.match(/打赏了\s*(.*?)\s*[：|:]\s*(.*)/);
                        if (match) {
                            donateHtml = `<span class="donate-highlight">💎 打赏了 ${match[1]}</span>`;
                            displayContent = match[2];
                        } else {
                             donateHtml = `<span class="donate-highlight">💎 礼物打赏</span>`;
                        }
                    }

                    html += `
                        <div class="cm-card ${isDonate ? 'donate' : ''}">
                            <div class="cm-avatar">${cm.avatar}</div>
                            <div class="cm-main">
                                <div class="cm-header">
                                    <span class="cm-user">${cm.user}</span>
                                    <span class="cm-time">${cm.time}</span>
                                </div>
                                <div class="cm-text">
                                    ${donateHtml}
                                    ${displayContent}
                                </div>
                            </div>
                        </div>
                    `;
                });

                html += `</div>`;
                container.innerHTML = html;
            }

            // 稍微延时以等待DOM
            setTimeout(renderLiveV2, 100);
        })();
    </script>
</body>
</html>
