                    </div>
                </div>

                <div class="sticky-note">
                    <b>Note:</b> <span id="view-note"></span>
                </div>
            </div>

            <!-- 控制按钮 -->
            <div class="page-ctrl">
                <div class="arrow-btn" onclick="changeDiaryPageV4(-1)">←</div>
                <span class="page-num" id="page-indicator">1 / 3</span>
                <div class="arrow-btn" onclick="changeDiaryPageV4(1)">→</div>
            </div>
        </div>
    </div>

    <script>
        (function() {
            // 初始化数据填充
            const store = document.getElementById('diaryDataStore');
            if (store) {
                const setData = (id, key) => {
                    const el = document.getElementById(id);
                    if(el) el.innerText = store.dataset[key] || '...';
                };
                ['date','dur','loc','trig','toys','fantasyObj','fantasyScene','highlight',
                 'climaxCount','climaxDesc','afterDesc','shame','satisfy','note'
                ].forEach(k => setData('view-'+k.replace(/[A-Z]/g, m => '-'+m.toLowerCase()), k));
            }

            // 逻辑 V4
            window.diaryPageIdx = 0;
            const total = 3;

            window.changeDiaryPageV4 = function(diff) {
                const p1 = document.getElementById('page-1');
                const p2 = document.getElementById('page-2');
                const p3 = document.getElementById('page-3');
                const pages = [p1, p2, p3];
                const indicator = document.getElementById('page-indicator');

                if(pages[window.diaryPageIdx]) pages[window.diaryPageIdx].classList.remove('active');

                window.diaryPageIdx = (window.diaryPageIdx + diff + total) % total;

                if(pages[window.diaryPageIdx]) pages[window.diaryPageIdx].classList.add('active');
                if(indicator) indicator.innerText = (window.diaryPageIdx + 1) + ' / ' + total;
            };

            window.toggleDiaryV4 = function(cover) {
                const wrapper = cover.closest('.diary-wrapper');
                const paper = wrapper.querySelector('.diary-paper');
                const lock = document.getElementById('diary-lock-icon');

                if (paper.classList.contains('open')) {
                    paper.classList.remove('open');
                    if(lock) lock.innerText = '🔒';
                } else {
                    paper.classList.add('open');
                    if(lock) lock.innerText = '🔓';
                }
            };
        })();
    </script>
</body>
</html>
