        document.getElementById('babyStatusLog').addEventListener('click', (e) => {
            const wrapper = e.currentTarget;

            // 处理面板折叠
            if (e.target.closest('.baby-log-header')) {
                wrapper.classList.toggle('is-open');
                return;
            }

            // 处理 Tab 切换
            const tab = e.target.closest('.baby-tab');
            if (tab && !tab.classList.contains('active')) {
                const tabs = Array.from(tab.parentNode.children);
                const index = tabs.indexOf(tab);
                const content = tab.closest('.baby-content');

                // 移除旧的 active 类，赋予新的 active 类
                content.querySelectorAll('.active').forEach(el => el.classList.remove('active'));
                tab.classList.add('active');
                content.querySelectorAll('.baby-page')[index].classList.add('active');
            }
        });
