        .th-music-player.collapsed.mini:hover {
            transform: scale(1);
            opacity: 1;
            box-shadow: 0 4px 15px var(--th-mp-shadow);
        }

        /* 展开状态 (胶囊) */
        .th-music-player.expanded {
            width: 340px;
            padding-right: 24px;
        }

        /* 封面区域 */
        .th-mp-cover-wrapper {
            width: 60px;
            height: 60px;
            flex-shrink: 0;
            position: relative;
            cursor: pointer;
            z-index: 2;
            -webkit-touch-callout: none;
            -webkit-user-select: none;
            user-select: none;
        }

        .th-mp-cover {
            width: 100%;
            height: 100%;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--th-mp-accent-dark), var(--th-mp-accent-light));
            background-size: cover;
            background-position: center;
            border: none;
            box-shadow: 0 4px 12px var(--th-mp-shadow), inset 0 1px 4px var(--th-mp-white-alpha-10);
            display: flex;
            align-items: center;
            justify-content: center;
            transition: transform 0.3s ease;
