             top: 220px;
        }

        .th-mp-playlist.show {
            opacity: 1;
            visibility: visible;
            transform: translateY(0);
            max-height: 180px;
            padding: 8px 0;
            box-shadow: 0 6px 20px var(--th-mp-shadow);
            overflow-y: auto;
