             flex: 1;
             gap: 8px;
             align-items: baseline;
             overflow: hidden;
        }

        .th-mp-playlist-del {
            width: 24px;
            height: 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 4px;
            opacity: 0;
            transition: all 0.2s;
            flex-shrink: 0;
        }
        /* 移动端适配：触摸设备或小屏幕始终显示删除按钮 */
        @media (pointer: coarse), (max-width: 768px) {
            .th-mp-playlist-del { opacity: 0.6; }
            /* 修正移动端默认位置 */
            .th-music-player {
                top: 120px;
                right: 10px;
                bottom: auto;
            }
        }
        .th-mp-playlist-item:hover .th-mp-playlist-del { opacity: 0.8; }
        .th-mp-playlist-del:hover {
            opacity: 1 !important;
            background: var(--th-mp-white-alpha-10);
            color: var(--th-mp-accent);
        }
        .th-mp-playlist-del svg { width: 16px; height: 16px; fill: currentColor; }

        .th-mp-playlist::-webkit-scrollbar { width: 4px; }
        .th-mp-playlist::-webkit-scrollbar-thumb { background: var(--th-mp-accent-dark); border-radius: 2px; }

        /* 主题切换面板 */
        .th-mp-theme-panel {
            position: absolute;
            bottom: 70px;
            left: 30px;
            transform: translateX(-50%) translateY(10px) scale(0.9);
            background: var(--th-mp-bg);
            padding: 0; /* 默认无内边距 */
            border-radius: 8px;
            display: flex;
            flex-direction: column;
            gap: 0;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
