        .th-mp-theme-panel.show {
            opacity: 1;
            visibility: visible;
            transform: translateX(-50%) translateY(0) scale(1);
            pointer-events: auto;
            max-height: 300px; /* 展开高度 */
            padding: 5px 0;
            box-shadow: 0 4px 15px var(--th-mp-shadow);
        }
        .th-mp-theme-item {
            padding: 8px 12px;
