                <div class="th-mp-lyrics-content" id="th-mp-lyrics-content"></div>
            </div>
        `;

        doc.body.appendChild(player);

        // 绑定歌词面板工具按钮
        const btnPos = doc.getElementById('th-mp-lrc-pos');
        const btnTheme = doc.getElementById('th-mp-lrc-theme');

        if(btnPos) {
            btnPos.addEventListener('click', toggleLyricsPosition);
            btnPos.addEventListener('pointerdown', (e) => e.stopPropagation()); // 防止触发拖拽
        }
        if(btnTheme) {
            btnTheme.addEventListener('click', toggleLyricsTheme);
            btnTheme.addEventListener('pointerdown', (e) => e.stopPropagation()); // 防止触发拖拽
        }

        // 绑定事件
        doc.getElementById('th-mp-play').onclick = togglePlay;
        doc.getElementById('th-mp-mode').onclick = cycleMode;
        doc.getElementById('th-mp-prev').onclick = () => switchTrack('prev');
        doc.getElementById('th-mp-next').onclick = () => switchTrack('next');
        doc.getElementById('th-mp-list-btn').onclick = togglePlaylist;
        doc.getElementById('th-mp-lyrics-btn').onclick = toggleLyrics;

        // 主题切换绑定
        const themeItems = player.querySelectorAll('.th-mp-theme-item');
        themeItems.forEach(item => {
            item.addEventListener('click', (e) => {
                e.stopPropagation();
                switchTheme(item.dataset.theme);
            });
            item.addEventListener('pointerdown', (e) => e.stopPropagation()); // 防止拖拽
        });

        // 闲置检测事件
        player.addEventListener('mouseenter', resetIdleTimer);
        player.addEventListener('mousemove', resetIdleTimer);
        player.addEventListener('mouseleave', startIdleTimer);

        // 拖拽逻辑
        makeDraggable(player);

        // 初始化状态
        syncUIWithSettings();
        renderPlaylist();
        startIdleTimer();

        // 点击外部自动收起
        const onDocClick = (e) => {
            if (!doc.body.contains(player)) {
                doc.removeEventListener('click', onDocClick);
                return;
            }

            if (!player.classList.contains('collapsed') && !e.composedPath().includes(player)) {
                toggleCollapse();
            }
        };
        setTimeout(() => doc.addEventListener('click', onDocClick), 0);
    }

    // 闲置自动缩小逻辑
    function startIdleTimer() {
        clearTimeout(idleTimer);
        const player = doc.getElementById(PLAYER_ID);
        if (!player) return;

        idleTimer = setTimeout(() => {
            if (isCollapsed && !isLyricsEnabled) {
                player.classList.add('mini');
            }
        }, 6000);
    }

    function resetIdleTimer() {
        clearTimeout(idleTimer);
        const player = doc.getElementById(PLAYER_ID);
        if (player) player.classList.remove('mini');
    }

    // 拖拽功能实现
    function makeDraggable(element) {
        let isDragging = false;
        let startX, startY, initialLeft, initialTop;
        let startTarget = null;
        let longPressTimer = null;
        let isLongPress = false;

        const toggleBtn = doc.getElementById('th-mp-toggle-collapse');
        if (toggleBtn) {
            // 右键菜单
            toggleBtn.addEventListener('contextmenu', (e) => {
                e.preventDefault();
                toggleThemePanel();
            });
        }

        const onPointerDown = (e) => {
            if (e.target.closest('.th-mp-btn') || e.target.closest('.th-mp-playlist') || e.target.closest('.th-mp-theme-panel')) return;

            isDragging = true;
            startTarget = e.target;
            element.setAttribute('data-dragging', 'false');
            element.setPointerCapture(e.pointerId);

            // 长按检测
            if (startTarget.closest('#th-mp-toggle-collapse')) {
                isLongPress = false;
                longPressTimer = setTimeout(() => {
                    if (!element.getAttribute('data-dragging') || element.getAttribute('data-dragging') === 'false') {
                         isLongPress = true;
                         toggleThemePanel();
                    }
                }, 600);
            }

            const rect = element.getBoundingClientRect();
            initialLeft = rect.left;
            initialTop = rect.top;

            startX = e.clientX;
            startY = e.clientY;

            element.style.bottom = 'auto';
            element.style.right = 'auto';
            element.style.left = `${initialLeft}px`;
            element.style.top = `${initialTop}px`;

            element.addEventListener('pointermove', onPointerMove);
            element.addEventListener('pointerup', onPointerUp);
        };

        const onPointerMove = (e) => {
            if (!isDragging) return;
            const dx = e.clientX - startX;
            const dy = e.clientY - startY;

            if(Math.abs(dx) > 5 || Math.abs(dy) > 5) {
                element.setAttribute('data-dragging', 'true');
                if (longPressTimer) {
                    clearTimeout(longPressTimer);
                    longPressTimer = null;
                }
            }

            element.style.left = `${initialLeft + dx}px`;
            element.style.top = `${initialTop + dy}px`;
        };

        const onPointerUp = (e) => {
            isDragging = false;
            if (longPressTimer) clearTimeout(longPressTimer);

            element.releasePointerCapture(e.pointerId);
            element.removeEventListener('pointermove', onPointerMove);
            element.removeEventListener('pointerup', onPointerUp);

            localStorage.setItem('th_mp_pos', JSON.stringify({
                left: element.style.left,
                top: element.style.top
            }));

            if (element.getAttribute('data-dragging') === 'false' && !isLongPress) {
                if (startTarget && startTarget.closest('#th-mp-toggle-collapse')) {
                    toggleCollapse();
                }
            }
        };

        element.addEventListener('pointerdown', onPointerDown);
    }

    // 折叠/展开
    function toggleCollapse() {
        const player = doc.getElementById(PLAYER_ID);
        const playlist = doc.getElementById('th-mp-playlist-panel');
        const lyricsPanel = doc.getElementById('th-mp-lyrics-panel');
        const themePanel = doc.getElementById('th-mp-theme-panel');

        // 任何状态切换都先关闭主题面板
        if(themePanel) themePanel.classList.remove('show');

        isCollapsed = !isCollapsed;

        if (isCollapsed) {
            player.classList.add('collapsed');
            player.classList.remove('expanded');

            // 收起时强制关闭所有面板
            if (lyricsPanel) lyricsPanel.classList.remove('show');
            if (playlist) playlist.classList.remove('show');

            startIdleTimer();
        } else {
            player.classList.remove('collapsed');
            player.classList.add('expanded');
            player.classList.remove('mini');
            clearTimeout(idleTimer);

            if (isLyricsEnabled && lyricsPanel) {
                lyricsPanel.classList.add('show');
            }
        }
    }

    function toggleThemePanel() {
        const panel = doc.getElementById('th-mp-theme-panel');
        if (panel) {
            panel.classList.toggle('show');
            // 如果打开了主题面板，重置闲置计时器
            if (panel.classList.contains('show')) {
                resetIdleTimer();
            } else {
                startIdleTimer();
            }
        }
    }

