    // 获取歌词
    async function fetchAndRenderLyrics() {
        if (!isLyricsEnabled) return;

        const renderingKey = currentKey;
        const music = MUSIC_CONFIG[renderingKey];
        if (!music || !music.title) return;

        const lyricsContent = doc.getElementById('th-mp-lyrics-content');
        const floatText = doc.getElementById('th-mp-float-lyrics-text');

        // 如果配置了禁用歌词
        if (music.noLyrics) {
            lyricsContent.innerHTML = '<div style="padding:20px;">...</div>';
            floatText.innerHTML = '';
            lyricsData = [];
            return;
        }

        lyricsContent.innerHTML = '<div style="padding:20px;">搜索歌词资源...</div>';
        floatText.innerHTML = '<span style="font-size:12px">...</span>';
        lyricsData = [];

        let foundLrc = null;
        let foundTrans = null;

        try {
            // 1. 搜索歌曲 ID
            const keyword = `${music.title} ${music.artist || ''}`;
            const searchUrl = `https://music-api.gdstudio.xyz/api.php?types=search&source=netease&name=${encodeURIComponent(keyword)}&count=1&pages=1`;

            const searchRes = await fetch(searchUrl);
            const searchData = await searchRes.json();

            if (searchData && searchData.length > 0) {
                const track = searchData[0];
                const lyricId = track.lyric_id;

                // 2. 获取歌词
                if (lyricId) {
                    const lrcUrl = `https://music-api.gdstudio.xyz/api.php?types=lyric&source=netease&id=${lyricId}`;
                    const lrcRes = await fetch(lrcUrl);
                    const lrcData = await lrcRes.json();

                    if (lrcData.lyric) {
                        foundLrc = lrcData.lyric;
                        foundTrans = lrcData.tlyric || null;
                    }
                }
            }
        } catch (err) {
            console.warn('[MusicPlayer] GDStudio API fetch failed:', err);
        }

        // // 备选策略: Lrclib
        // if (!foundLrc) {
        //      try {
        //         const query = `${music.title} ${music.artist || ''}`;
        //         const res = await fetch(`https://lrclib.net/api/search?q=${encodeURIComponent(query)}`);
        //         if (res.ok) {
        //             const data = await res.json();
        //             if (data && data.length > 0) {
        //                 const hit = data.find(d => d.syncedLyrics) || data[0];
        //                 if (hit.syncedLyrics) foundLrc = hit.syncedLyrics;
        //             }
        //         }
        //     } catch(err) { console.warn('Lrclib failed:', err); }
        // }

        // 防止异步请求回来时已经切歌
        if (renderingKey !== currentKey) return;

        if (foundLrc) {
            parseLyrics(foundLrc, foundTrans);
            renderLyricsPanel();
            // 强制重新同步一次
            stopLyricsSync();
            startLyricsSync();
        } else {
             lyricsContent.innerHTML = '<div style="padding:20px;">未找到歌词资源</div>';
             floatText.innerHTML = '<span style="font-size:12px">未找到歌词资源</span>';
        }
    }

    function parseLyrics(lrcText, tLrcText) {
        lyricsData = [];
        const regex = /^\[(\d{2}):(\d{2})\.(\d{2,3})\](.*)$/;

        // 解析主歌词
        const parse = (text) => {
            const map = new Map();
            if (!text) return map;
            text.split('\n').forEach(line => {
                const match = line.match(regex);
                if (match) {
                    const min = parseInt(match[1]);
                    const sec = parseInt(match[2]);
                    const ms = parseInt(match[3].padEnd(3, '0'));
                    const time = min * 60 + sec + ms / 1000;
                    const content = match[4].trim();
                    if (content) map.set(time.toFixed(3), content); // 使用字符串key避免浮点误差
                }
            });
            return map;
        };

        const lrcMap = parse(lrcText);
        const tLrcMap = parse(tLrcText);

        // 合并
        const sortedTimes = Array.from(lrcMap.keys()).sort((a, b) => parseFloat(a) - parseFloat(b));

        sortedTimes.forEach(timeStr => {
            lyricsData.push({
                time: parseFloat(timeStr),
                text: lrcMap.get(timeStr),
                trans: tLrcMap.get(timeStr) || ''
            });
        });
    }

    function renderLyricsPanel() {
        const content = doc.getElementById('th-mp-lyrics-content');
        if (!content) return;
        content.innerHTML = '';

        // 前后空白
        const padding = doc.createElement('div');
        padding.style.height = '60px';
        content.appendChild(padding.cloneNode());

        lyricsData.forEach((line, index) => {
            const div = doc.createElement('div');
            div.className = 'th-mp-lyrics-line';
            div.dataset.index = index;

            // 彩蛋
            let processedText = line.text;
            const loveKeywords = ['爱','爱情', '愛情', 'love', 'Love', 'LOVE', '愛', '사랑'];
            loveKeywords.forEach(kw => {
                 processedText = processedText.replace(new RegExp(kw, 'g'), `<span class="th-mp-lyrics-love">${kw}</span>`);
            });

            div.innerHTML = `<div>${processedText}</div>${line.trans ? `<div style="font-size:11px;opacity:0.7">${line.trans}</div>` : ''}`;
            content.appendChild(div);
        });

        content.appendChild(padding.cloneNode());
    }

    // 渲染播放列表
    function renderPlaylist() {
        const panel = doc.getElementById('th-mp-playlist-panel');
        if (!panel) return;
        panel.innerHTML = '';

        Object.keys(MUSIC_CONFIG).filter(k => k !== 'null').forEach(key => {
            const track = MUSIC_CONFIG[key];
            const item = doc.createElement('div');
            item.className = `th-mp-playlist-item ${key === currentKey ? 'active' : ''}`;

            const isDeletable = key !== 'default';

            item.innerHTML = `
                <div class="th-mp-playlist-info">
                    <span style="font-weight:bold;white-space:nowrap;">${track.title}</span>
                    <span style="font-size:0.9em;opacity:0.8;text-overflow:ellipsis;overflow:hidden;white-space:nowrap;">${track.artist}</span>
                </div>
                ${isDeletable ? `<div class="th-mp-playlist-del" title="从列表中移除">${ICONS.delete}</div>` : ''}
            `;

            item.addEventListener('click', (e) => {
                 playTrackByKey(key);
                 togglePlaylist();
            });

            if (isDeletable) {
                const delBtn = item.querySelector('.th-mp-playlist-del');
                if (delBtn) {
                    delBtn.addEventListener('click', (e) => {
                        e.stopPropagation();
                        deleteFromPlaylist(key);
                    });
