          e.preventDefault();
        }
        saveSettings();
        $quickOverlay.hide();
        if (!anyOverlayVisible()) unlockScroll(parentDoc);
        alignVisibleOverlays();
      };
      const closeMainMenu = (e) => {
        if (e) {
          e.preventDefault();
        }
        saveSettings();
        lastScrollPosition = 0;
        $mainOverlay.hide();
        if (!anyOverlayVisible()) unlockScroll(parentDoc);
        alignVisibleOverlays();
