        fitQuickMenu();
        fitCustomizePanel();
        alignVisibleOverlays();
      };
      if (vv) {
        vv.addEventListener("resize", onVVChange);
        vv.addEventListener("scroll", onVVChange);
      }
      const redrawPickers = () => {
        try {
          drawHue();
          drawAlpha();
          drawSV();
        } catch (_) {}
      };
      window.parent.addEventListener("resize", () => {
        ensureBallInViewport();
        onVVChange();
      });
      window.parent.addEventListener("orientationchange", () => {
        setTimeout(() => {
          ensureBallInViewport();
          fitMainPanel();
          fitQuickMenu();
          fitCustomizePanel();
